// src/obsidian/processors/dropProcessor.ts
var DropProcessor = class {
  slideCommentRegex = /<!--\s*(?:\.)?slide.*-->/;
  parser = new CommentParser();
  process(markdown, options) {
    let output = markdown;
    markdown.split(new RegExp(options.separator, "gmi")).map((slidegroup) => {
      return slidegroup.split(new RegExp(options.verticalSeparator, "gmi")).map((slide) => {
        if (slide.trim().length > 0) {
          const newSlide = this.transformSlide(
            slide,
            options
          );
          const split = output.split(slide);
          if (split.length === 2) {
            output = split.join(newSlide);
          } else {
            const right = split.splice(1).join(slide);
            const left = split[0];
            const both = [left, right];
            output = both.join(newSlide);
          }
          return newSlide;
        }
        return slide;
      }).join(options.verticalSeparator);
    }).join(options.separator);
    return output;
  }
  transformSlide(slide, options) {
    const [md2, notes] = this.extractNotes(slide, options);
    let outMd;
    let outSlideComment;
    if (this.slideCommentRegex.test(md2)) {
      const [match] = this.slideCommentRegex.exec(md2);
      const comment = this.parser.parseLine(match);
      comment.addClass("drop");
      outMd = md2.replace(this.slideCommentRegex, "");
      outMd = outMd.trim();
      outSlideComment = this.parser.commentToString(comment);
    } else {
      outMd = md2.trim();
      outSlideComment = '<!-- .slide: class="drop" -->';
    }
    let out = `${outSlideComment}
<grid absolute="true" drag="100 100" drop="0 0">
${outMd}
</grid>`;
    if (notes.length > 0) {
      out += `

${notes}`;
    }
    return out;
  }
  extractNotes(input, options) {
    let noteSeparator = "note:";
    if (options.notesSeparator && options.notesSeparator.length > 0) {
      noteSeparator = options.notesSeparator;
    }
    const spliceIdx = input.indexOf(noteSeparator);
    if (spliceIdx > 0) {
      return [input.substring(0, spliceIdx), input.substring(spliceIdx)];
    }
    return [input, ""];
  }
};

