var TemplateManager = class {
  plugin;
  app;
  builtInTemplates = /* @__PURE__ */ new Map();
  userTemplates = /* @__PURE__ */ new Map();
  constructor(plugin) {
    this.plugin = plugin;
    this.app = plugin.app;
  }
  async loadTemplates() {
    await this.loadBuiltInTemplates();
    await this.loadUserTemplates();
  }
  async loadBuiltInTemplates() {
    for (const templateDef of BUILT_IN_TEMPLATES) {
      const content = this.getBuiltInTemplateContent(templateDef.id);
      this.builtInTemplates.set(templateDef.id, {
        ...templateDef,
        content
      });
    }
  }
  async loadUserTemplates() {
    const userTemplatePath = this.plugin.settings.userTemplatesFolder;
    if (!userTemplatePath) return;
    const folder = this.app.vault.getAbstractFileByPath((0, import_obsidian10.normalizePath)(userTemplatePath));
    if (!folder || folder.constructor.name !== "TFolder") return;
    const files = this.app.vault.getMarkdownFiles().filter(
      (f) => f.path.startsWith(userTemplatePath)
    );
    for (const file of files) {
      const content = await this.app.vault.read(file);
      const id = file.basename.replace("slide-", "");
      this.userTemplates.set(id, {
        id: `user-${id}`,
        name: this.formatName(id),
        category: "Custom",
        content,
        description: "User template",
        icon: "\u2B50"
      });
    }
  }
  formatName(id) {
    return id.split("-").map((word) => word.charAt(0).toUpperCase() + word.slice(1)).join(" ");
  }
  getAllTemplates() {
    const all = [];
    this.builtInTemplates.forEach((t) => all.push(t));
    this.userTemplates.forEach((t) => all.push(t));
    return all;
  }
  getCategories() {
    const categories = /* @__PURE__ */ new Set();
    this.getAllTemplates().forEach((t) => categories.add(t.category));
    return Array.from(categories);
  }
  getTemplatesByCategory(category) {
    return this.getAllTemplates().filter((t) => t.category === category);
  }
  getTemplate(id) {
    return this.builtInTemplates.get(id) || this.userTemplates.get(id);
  }
  getBuiltInTemplateContent(id) {
    return ALL_TEMPLATE_CONTENT[id] || `---

## Slide Title

Content here`;
  }
};

